public Vector3f cross(float x, float y, float z, Vector3f dest) {
        float rx = this.y * z - this.z * y;
        float ry = this.z * x - this.x * z;
        float rz = this.x * y - this.y * x;
        dest.x = rx;
        dest.y = ry;
        dest.z = rz;
        return dest;
    }

